// TestActionNames asserts every announced pkg action name is a registered constant.
func TestActionNames(t *testing.T) {

	names := []op.ActionName{
		provider.Install,
		provider.Installed,
		provider.NotInstalled,
		provider.Observe,
		provider.Remove,
		provider.Update,
		provider.Upgrade,
		provider.VersionGTE,
	}
	for _, name := range names {
		a := getAction(t, name)
		if got := a.Name(); got != name {
			t.Errorf("Name() = %q, want %q", got, name)
		}
	}
}

